// Shared TypeSafe (System One / Jev) integration: real-time AI slop detection.
// Used by the extension service worker and by test/live-check.mjs in Node.
// Docs: https://docs.typesafe.ai/api  (POST /v1/systemone, Noul questions)

export const TYPESAFE_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
export const TYPESAFE_MODELS_ENDPOINT = "https://api.typesafe.ai/v1/models";
export const DEFAULT_MODEL = "jev-latest";

// Jev context limits (docs/model-jaggedness): 64k tokens for state + all
// questions, 32k for state + longest question. ~30 compact cards stay
// far below that; the content script also batches with this cap.
export const MAX_CANDIDATES_PER_REQUEST = 30;

// Bands owned by code; Jev only returns the probability.
export const HIGH_THRESHOLD = 0.7; // >= high  -> LIKELY AI SLOP badge
// MEDIUM band: 0.4 <= p < 0.7 -> CHECK THIS outline. Below: untouched.
export const MEDIUM_THRESHOLD = 0.4;

export function bandFor(p) {
  if (p >= HIGH_THRESHOLD) return "high";
  if (p >= MEDIUM_THRESHOLD) return "medium";
  return "low";
}

const SLOP_CRITERIA = {
  true:
    "AI-generated low-effort feed filler ('slop'): generic engagement-bait with a vague hook and no verifiable specifics, " +
    "repetitive formulaic listicles or 'top 10' compilations with stock phrasing, keyword-stuffed SEO filler that restates the headline " +
    "without adding facts, synthetic inspirational quotes over stock imagery, or text with telltale LLM tics " +
    "(excessive em-dashes, 'delve', 'game-changer', 'unlock', breathless superlatives) and no named sources, dates, places, or data.",
  false:
    "Genuine human-authored content: reporting with named people, places, dates, quotes or data, " +
    "first-person experience with concrete detail, substantive analysis or argument, " +
    "or ordinary site interface (navigation, headers, footers, comments, related links).",
};

/**
 * Build the System One request for a batch of feed cards.
 * Every card gets its own Noul question over the same state, so the
 * whole batch is one API call (speculative fan-out pattern).
 */
export function buildRequest({ page, candidates, model = DEFAULT_MODEL }) {
  if (!Array.isArray(candidates) || candidates.length === 0) {
    throw new Error("buildRequest: candidates must be a non-empty array");
  }
  if (candidates.length > MAX_CANDIDATES_PER_REQUEST) {
    throw new Error(`buildRequest: at most ${MAX_CANDIDATES_PER_REQUEST} candidates per request`);
  }
  const questions = {};
  candidates.forEach((_, i) => {
    questions[`slop_${i}`] = {
      type: "noul",
      instructions:
        `Is the feed card \`candidates[${i}]\` AI-generated low-effort filler ("slop")? ` +
        "Judge it by its text quality, specificity, sourcing, and voice, in the context of `page`. " +
        "Polished marketing copy from a real brand is not slop unless it shows the low-effort generic traits above.",
      criteria: SLOP_CRITERIA,
    };
  });
  return { model, state: { page, candidates }, questions };
}

/** Extract the per-card "is slop" probabilities from a response body. */
export function parseResponse(body, count) {
  const probabilities = [];
  for (let i = 0; i < count; i++) {
    const answer = body?.answers?.[`slop_${i}`];
    if (!answer || answer.type !== "noul" || typeof answer.noul !== "number") {
      throw new Error(`parseResponse: missing noul answer for candidate ${i}`);
    }
    probabilities.push(answer.noul);
  }
  return { model: body.model, probabilities, usage: body.usage };
}

const RETRYABLE = new Set([429, 529, 500, 502, 503, 504]);

async function postWithRetry({ url, apiKey, payload, fetchImpl, attempts = 4 }) {
  let lastError;
  for (let attempt = 0; attempt < attempts; attempt++) {
    let res;
    try {
      res = await fetchImpl(url, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });
    } catch (err) {
      lastError = err;
      await sleep(backoffMs(attempt));
      continue;
    }
    if (res.ok) return res.json();

    const text = await res.text().catch(() => "");
    lastError = new Error(`TypeSafe API ${res.status}: ${text.slice(0, 300)}`);
    if (!RETRYABLE.has(res.status)) throw lastError;

    const retryAfter = Number(res.headers.get("retry-after"));
    await sleep(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : backoffMs(attempt));
  }
  throw lastError;
}

function backoffMs(attempt) {
  return 500 * 2 ** attempt + Math.random() * 250;
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/**
 * Judge a batch of feed cards. Returns { model, probabilities, usage }.
 * probabilities[i] is P(candidates[i] is AI slop) in [0, 1].
 */
export async function judgeCandidates({ apiKey, page, candidates, model, fetchImpl = globalThis.fetch }) {
  if (!apiKey) throw new Error("No TypeSafe API key set.");
  const payload = buildRequest({ page, candidates, model });
  const body = await postWithRetry({ url: TYPESAFE_ENDPOINT, apiKey, payload, fetchImpl });
  return parseResponse(body, candidates.length);
}

/** GET /v1/models – used by the popup's "Test" button. */
export async function listModels({ apiKey, fetchImpl = globalThis.fetch }) {
  if (!apiKey) throw new Error("No TypeSafe API key set.");
  const res = await fetchImpl(TYPESAFE_MODELS_ENDPOINT, {
    headers: { Authorization: `Bearer ${apiKey}` },
  });
  if (!res.ok) throw new Error(`TypeSafe API ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const body = await res.json();
  return body.models ?? [];
}

