args.new_string:
// Content script: real-time AI slop detector. Jev judges each feed card;
// high confidence -> LIKELY AI SLOP badge with score, medium -> CHECK THIS
// outline, low -> untouched. Content is NEVER removed or hidden.
//
// Division of labour:
//   code -> card discovery, compact description, batching, bands, badges
//   Jev  -> the semantic judgment "is this card AI-generated slop?"
(() => {
  if (window.__tsabLoaded) return;
  window.__tsabLoaded = true;

  const DEFAULTS = { apiKey: "", enabled: true, highThreshold: 0.7, mediumThreshold: 0.4, toast: true };
  const MAX_PER_BATCH = 30;
  const DEBOUNCE_MS = 600;
  const OWN_ATTR = "data-tsab"; // marks our own UI so it is never a candidate
  const CARD_SELECTOR = "[data-feed-card], article.feed-card, .feed-card, article.post-card, .post-card";

  const settings = { ...DEFAULTS };
  let judged = new WeakSet();
  const pending = new Set();
  let timer = null;
  let busy = false;
  let flaggedOnPage = 0;
  let lastError = null;
  let lastLatencyMs = null;

  function isOurs(el) { return !!el.closest?.(`[${OWN_ATTR}]`); }

  function isVisible(el) {
    if (!el.isConnected) return false;
    const r = el.getBoundingClientRect();
    if (r.width < 8 || r.height < 8) return false;
    const cs = getComputedStyle(el);
    return cs.display !== "none" && cs.visibility !== "hidden";
  }

  function acceptable(el) {
    if (!el || el === document.body || el === document.documentElement) return false;
    if (isOurs(el)) return false;
    if (judged.has(el)) return false;
    if (!isVisible(el)) return false;
    if ((el.innerText || "").trim().length < 10) return false;
    return true;
  }

  function collectCandidates(root) {
    const scope = root.nodeType === Node.ELEMENT_NODE ? root : document.body;
    if (!scope) return [];
    const out = new Set();
    if (scope.matches?.(CARD_SELECTOR)) out.add(scope);
    scope.querySelectorAll(CARD_SELECTOR).forEach((el) => out.add(el));
    return [...out].filter(acceptable);
  }

  function describe(el) {
    const text = (el.innerText || "").replace(/\s+/g, " ").trim().slice(0, 400);
    const author = el.querySelector("[data-author]")?.textContent?.trim()?.slice(0, 80) || undefined;
    const c = {
      tag: el.tagName.toLowerCase(),
      id: el.id || el.getAttribute("data-feed-card") || undefined,
      author,
      text: text || undefined,
    };
    for (const k of Object.keys(c)) if (c[k] === undefined) delete c[k];
    return c;
  }

  function bandFor(p) {
    if (p >= settings.highThreshold) return "high";
    if (p >= settings.mediumThreshold) return "medium";
    return "low";
  }

  function badge(el, p, band) {
    el.style.position ||= "relative";
    const tag = document.createElement("div");
    tag.setAttribute(OWN_ATTR, "");
    if (band === "high") {
      el.style.outline = "3px solid #e11d48";
      el.style.outlineOffset = "-3px";
      tag.textContent = `\u{1F916} LIKELY AI SLOP ${(p * 100).toFixed(0)}%`;
      Object.assign(tag.style, {
        position: "absolute", top: "8px", right: "8px", zIndex: "2147483646",
        background: "#e11d48", color: "#fff", font: "bold 12px system-ui, sans-serif",
        padding: "4px 10px", borderRadius: "999px", pointerEvents: "none",
        boxShadow: "0 2px 8px rgba(0,0,0,.3)",
      });
    } else {
      el.style.outline = "3px dashed #f59e0b";
      el.style.outlineOffset = "-3px";
      tag.textContent = `CHECK THIS ${(p * 100).toFixed(0)}%`;
      Object.assign(tag.style, {
        position: "absolute", top: "8px", right: "8px", zIndex: "2147483646",
        background: "#fffbeb", color: "#92400e", border: "1px solid #f59e0b",
        font: "bold 11px system-ui, sans-serif",
        padding: "3px 8px", borderRadius: "999px", pointerEvents: "none",
      });
    }
    el.appendChild(tag);
    el.setAttribute("data-slop-band", band);
    el.setAttribute("data-slop-score", p.toFixed(3));
  }

  function showToast(msg) {
    if (!settings.toast) return;
    let host = document.getElementById("tsab-toast");
    if (!host) {
      host = document.createElement("div");
      host.id = "tsab-toast";
      host.setAttribute(OWN_ATTR, "");
      Object.assign(host.style, {
        position: "fixed", right: "16px", bottom: "16px", zIndex: "2147483647",
        background: "#0f172a", color: "#f8fafc", font: "13px/1.4 system-ui, sans-serif",
        padding: "10px 14px", borderRadius: "10px", boxShadow: "0 8px 24px rgba(0,0,0,.35)",
        transition: "opacity .3s", opacity: "0", pointerEvents: "none", maxWidth: "320px",
      });
      document.documentElement.appendChild(host);
    }
    host.textContent = msg;
    host.style.opacity = "1";
    clearTimeout(host._t);
    host._t = setTimeout(() => (host.style.opacity = "0"), 2200);
  }

  async function flush() {
    timer = null;
    if (busy) { schedule(); return; }
    if (!settings.enabled || !settings.apiKey) { pending.clear(); return; }
    const els = [...pending].filter(acceptable).slice(0, MAX_PER_BATCH);
    els.forEach((el) => pending.delete(el));
    if (!els.length) return;
    busy = true;
    try {
      els.forEach((el) => judged.add(el));
      const candidates = els.map(describe);
      const page = { host: location.hostname, title: (document.title || "").slice(0, 120) };
      const res = await chrome.runtime.sendMessage({ type: "judge", page, candidates });
      if (!res || res.error) {
        lastError = res?.error ?? "No response from the service worker";
        console.warn("[slop]", lastError);
        return;
      }
      lastError = null;
      lastLatencyMs = res.latencyMs ?? null;
      let hits = 0;
      res.probabilities.forEach((p, i) => {
        const band = bandFor(p);
        console.debug("[slop]", p.toFixed(2), band, candidates[i]);
        if (band === "low") return; // untouched
        if (!els[i].isConnected) return;
        badge(els[i], p, band);
        hits++;
      });
      if (hits) {
        flaggedOnPage += hits;
        chrome.runtime.sendMessage({ type: "blocked", count: hits }).catch(() => {});
        showToast(`\u{1F916} ${hits} card${hits === 1 ? "" : "s"} flagged · ${candidates.length} checked · ${res.latencyMs} ms`);
      }
      window.__slopDone = true;
      window.__slopScores = els.map((el, i) => ({ id: el.id || el.getAttribute("data-feed-card"), p: res.probabilities[i], band: bandFor(res.probabilities[i]) }));
    } catch (err) {
      lastError = err?.message ?? String(err);
      console.warn("[slop]", err);
    } finally {
      busy = false;
      if (pending.size) schedule();
    }
  }

  function schedule() { clearTimeout(timer); timer = setTimeout(flush, DEBOUNCE_MS); }

  function scan(root = document.body) {
    if (!root) return;
    for (const el of collectCandidates(root)) pending.add(el);
    if (pending.size) schedule();
  }

  const observer = new MutationObserver((mutations) => {
    if (!settings.enabled) return;
    for (const m of mutations) {
      if (m.type === "childList") {
        for (const n of m.addedNodes) if (n.nodeType === Node.ELEMENT_NODE && !isOurs(n)) scan(n);
      }
    }
  });

  function start() {
    scan(document.body);
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }

  chrome.storage.sync.get(DEFAULTS).then((s) => {
    Object.assign(settings, s);
    if (document.readyState === "loading") addEventListener("DOMContentLoaded", start, { once: true });
    else start();
  });

  chrome.storage.onChanged.addListener((changes, areaName) => {
    if (areaName !== "sync") return;
    for (const [k, { newValue }] of Object.entries(changes)) if (k in DEFAULTS) settings[k] = newValue;
  });

  chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
    if (msg?.type === "getStats") {
      sendResponse({ flaggedOnPage, pending: pending.size, lastError, lastLatencyMs });
    } else if (msg?.type === "rescan") {
      judged = new WeakSet();
      scan(document.body);
      sendResponse({ ok: true, pending: pending.size });
    }
    return false;
  });
})();

