// Calls the real TypeSafe API with the three fixture cards.
//   TYPESAFE_API_KEY=... node test/live-check.mjs
import { judgeCandidates, buildRequest } from "../src/typesafe.js";
import { summarize } from "../src/classify.js";

const page = { host: "feed.example", title: "Your feed" };
const candidates = [
  {
    author: "Growth Mindset Daily",
    text: "Let's dive in: 7 game-changing habits that separate the top 1% from everyone else. In today's fast-paced world, success isn't just about working hard — it's about working smart. Wake up before the world does. 92% of high performers do. Embrace failure as feedback. Your network is your net worth. Consistency beats intensity. Studies show people who apply these see a 3x increase in productivity. Which one resonates most with you? Follow for more daily insights! #success #mindset #growth",
    word_count: 95, emoji_count: 9, hashtag_count: 4, expect: "high",
  },
  {
    author: "Priya Raman",
    text: "Some thoughts on why remote work is here to stay. The pandemic fundamentally changed how teams operate. Companies that embrace flexibility are seeing better retention, while those that resist are struggling to attract talent. There are real trade-offs around onboarding and mentorship, and hybrid models come with coordination costs. But overall the direction seems clear enough. Curious what others are seeing.",
    word_count: 72, expect: "medium",
  },
  {
    author: "Tomas Weber",
    text: "Spent Tuesday chasing a p99 latency spike on our checkout service. Turned out to be connection-pool starvation: pgbouncer was set to pool_mode=session, so every idle transaction held a backend connection hostage. Flipped it to transaction, dropped default_pool_size from 100 to 25, and p99 went from 1,840 ms to 210 ms. Launch was in March 2024.",
    word_count: 68, expect: "low",
  },
];

const expectations = candidates.map((c) => c.expect);
const clean = candidates.map(({ expect, ...c }) => c);

const req = buildRequest({ page, candidates: clean });
console.log("request bytes:", JSON.stringify(req).length, "| questions:", Object.keys(req.questions).length);

const t0 = performance.now();
const result = await judgeCandidates({ apiKey: process.env.TYPESAFE_API_KEY, page, candidates: clean });
const latencyMs = Math.round(performance.now() - t0);
console.log("model:", result.model, "| latency ms:", latencyMs, "| usage:", result.usage);

const { verdicts } = summarize(result.probabilities);
let correct = 0;
for (const [i, p] of result.probabilities.entries()) {
  const ok = verdicts[i].tier === expectations[i];
  if (ok) correct++;
  const mark = verdicts[i].tier === "high" ? verdicts[i].badge : verdicts[i].label;
  console.log(`${ok ? "PASS" : "FAIL"} p=${p.toFixed(3)} tier=${verdicts[i].tier.padEnd(6)} expected=${expectations[i].padEnd(6)} ${mark ?? "(untouched)"} :: ${clean[i].author}`);
}
console.log(`${correct}/${candidates.length} correct`);
if (correct !== candidates.length) process.exit(1);

