const DEFAULTS = { apiKey: "", enabled: true, highThreshold: 0.75, mediumThreshold: 0.45, toast: true, showScore: true };
const $ = (id) => document.getElementById(id);

async function activeTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

async function loadStats() {
  const { totalFlagged = 0 } = await chrome.storage.local.get({ totalFlagged: 0 });
  $("statTotal").textContent = totalFlagged;
  const tab = await activeTab();
  if (!tab?.id) return;
  try {
    const s = await chrome.tabs.sendMessage(tab.id, { type: "getStats" });
    $("statPage").textContent = s?.flaggedOnPage ?? 0;
    const err = s?.lastError ? `Error: ${s.lastError}` : "";
    $("pageError").textContent = err;
    $("pageError").className = s?.lastError ? "hint error" : "hint";
  } catch {
    $("pageError").textContent = "Not active on this page (e.g. chrome://).";
    $("pageError").className = "hint";
  }
}

async function init() {
  const s = await chrome.storage.sync.get(DEFAULTS);
  $("enabled").checked = s.enabled;
  $("apiKey").value = s.apiKey;
  $("highThreshold").value = s.highThreshold;
  $("highValue").textContent = Number(s.highThreshold).toFixed(2);
  $("mediumThreshold").value = s.mediumThreshold;
  $("mediumValue").textContent = Number(s.mediumThreshold).toFixed(2);
  $("toast").checked = s.toast;
  $("showScore").checked = s.showScore;
  if (!s.apiKey) {
    $("keyStatus").textContent = "Enter your key \u2013 nothing happens without one.";
    $("keyStatus").className = "hint error";
  }
  await loadStats();
}

$("enabled").addEventListener("change", (e) => chrome.storage.sync.set({ enabled: e.target.checked }));
$("toast").addEventListener("change", (e) => chrome.storage.sync.set({ toast: e.target.checked }));
$("showScore").addEventListener("change", (e) => chrome.storage.sync.set({ showScore: e.target.checked }));
$("highThreshold").addEventListener("input", (e) => {
  $("highValue").textContent = Number(e.target.value).toFixed(2);
});
$("highThreshold").addEventListener("change", (e) => chrome.storage.sync.set({ highThreshold: Number(e.target.value) }));
$("mediumThreshold").addEventListener("input", (e) => {
  $("mediumValue").textContent = Number(e.target.value).toFixed(2);
});
$("mediumThreshold").addEventListener("change", (e) => chrome.storage.sync.set({ mediumThreshold: Number(e.target.value) }));

let keyTimer = null;
$("apiKey").addEventListener("input", (e) => {
  clearTimeout(keyTimer);
  const apiKey = e.target.value.trim();
  keyTimer = setTimeout(() => {
    chrome.storage.sync.set({ apiKey });
    $("keyStatus").textContent = apiKey ? "Saved." : "Enter your key \u2013 nothing happens without one.";
    $("keyStatus").className = apiKey ? "hint ok" : "hint error";
  }, 300);
});

$("testKey").addEventListener("click", async () => {
  $("keyStatus").textContent = "Checking\u2026";
  $("keyStatus").className = "hint";
  const res = await chrome.runtime.sendMessage({ type: "testKey" });
  if (res?.error) {
    $("keyStatus").textContent = `Error: ${res.error}`;
    $("keyStatus").className = "hint error";
  } else {
    $("keyStatus").textContent = `OK \u2013 models: ${res.models.join(", ")}`;
    $("keyStatus").className = "hint ok";
  }
});

$("rescan").addEventListener("click", async () => {
  const tab = await activeTab();
  if (!tab?.id) return;
  try {
    await chrome.tabs.sendMessage(tab.id, { type: "rescan" });
    setTimeout(loadStats, 1500);
  } catch {
    $("pageError").textContent = "Not active on this page.";
  }
});

init();

