args.new_string:
// Browser verification: loads the harness through the real relay (Jev),
// screenshots before/after, asserts the three treatments + never-remove.
// Assumes: static server on :8787 and relay on :8788 are already running.
//   node test/verify.mjs
import { chromium } from "playwright";
import fs from "node:fs";

const OUT = new URL("../assets/", import.meta.url);
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 700, height: 900 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));

// BEFORE: plain fixture, no judgments yet.
await page.goto("http://localhost:8787/test/fixture.html", { waitUntil: "networkidle" });
await page.waitForSelector("#card-clean");
const beforeText = await page.$$eval("[data-slop-card]", (els) => els.map((e) => e.innerText.length));
await page.screenshot({ path: new URL("../assets/before.png", import.meta.url), fullPage: true });
console.log("before: card text lengths", JSON.stringify(beforeText));

// AFTER: harness judges the same feed through the relay (real Jev).
await page.goto("http://localhost:8787/test/harness.html", { waitUntil: "networkidle" });
await page.waitForFunction(() => window.__tssdFixtureReady === true, null, { timeout: 10000 });
await page.waitForFunction(
  () => window.__tssd && window.__tssd.stats().checkedOnPage >= 3 && window.__tssd.stats().pending === 0 && !window.__tssd.stats().busy,
  null,
  { timeout: 60000, polling: 500 },
);
// Let the badge fade-in finish so the screenshot is stable.
await page.waitForTimeout(800);

const stats = await page.evaluate(() => window.__tssd.stats());
console.log("harness stats:", JSON.stringify(stats));
if (stats.lastError || window.__tssdRelayError) throw new Error("relay error: " + (stats.lastError || "?"));
const relayErr = await page.evaluate(() => window.__tssdRelayError);
if (relayErr) throw new Error("relay unreachable: " + relayErr);

const result = await page.evaluate(() => ({
  tiers: Object.fromEntries(
    [...document.querySelectorAll("[data-slop-card]")].map((el) => [el.id, el.getAttribute("data-tssd-tier")]),
  ),
  badges: [...document.querySelectorAll(".tssd-badge")].map((b) => b.textContent),
  scores: Object.fromEntries(
    [...document.querySelectorAll("[data-slop-card]")].map((el) => [el.id, el.getAttribute("data-tssd-score")]),
  ),
  afterText: [...document.querySelectorAll("[data-slop-card]")].map((el) =>
    el.cloneNode(true).querySelectorAll(".tssd-badge").forEach((n) => n.remove()) || true,
  ),
  cardCount: document.querySelectorAll("[data-slop-card]").length,
  chromeMarked: document.querySelector(".composer")?.hasAttribute("data-tssd-tier") ?? null,
}));
console.log(JSON.stringify(result, null, 1));

// Text-preservation check: strip our badges, compare visible text with BEFORE.
const afterText = await page.$$eval("[data-slop-card]", (els) =>
  els.map((el) => {
    const c = el.cloneNode(true);
    c.querySelectorAll(".tssd-badge").forEach((n) => n.remove());
    return (c.innerText || "").replace(/\\s+/g, " ").trim();
  }),
);
const beforeFull = await chromium.launch().then(async (b2) => {
  const p2 = await b2.newPage();
  await p2.goto("http://localhost:8787/test/fixture.html", { waitUntil: "networkidle" });
  const t = await p2.$$eval("[data-slop-card]", (els) =>
    els.map((el) => (el.innerText || "").replace(/\\s+/g, " ").trim()),
  );
  await b2.close();
  return t;
});

let pass = 0;
let fail = 0;
const check = (name, ok, detail = "") => {
  if (ok) pass++;
  else fail++;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " :: " + detail : ""}`);
};

check("3 cards present", result.cardCount === 3, String(result.cardCount));
check("slop card -> high", result.tiers["card-slop"] === "high", result.tiers["card-slop"]);
check(
  "high badge shows LIKELY AI SLOP + score",
  result.badges.some((b) => /LIKELY AI SLOP · \d+%/.test(b)),
  JSON.stringify(result.badges),
);
check("ambiguous card -> medium", result.tiers["card-ambiguous"] === "medium", result.tiers["card-ambiguous"]);
check(
  "medium gets CHECK THIS outline, no score badge",
  result.badges.some((b) => b === "CHECK THIS") && result.scores["card-ambiguous"] != null,
  JSON.stringify(result.badges),
);
check("clean card untouched", result.tiers["card-clean"] == null, result.tiers["card-clean"]);
check("feed chrome never judged", result.chromeMarked === false, String(result.chromeMarked));
check(
  "no card text removed or altered",
  JSON.stringify(afterText) === JSON.stringify(beforeFull),
  `before=${beforeFull.map((t) => t.length)} after=${afterText.map((t) => t.length)}`,
);
check("no page errors", errors.length === 0, errors.join(" | ").slice(0, 200));

await page.screenshot({ path: new URL("../assets/after.png", import.meta.url), fullPage: true });
// Close-up of the badged card for the PR.
await page.locator("#card-slop").screenshot({ path: new URL("../assets/badge-closeup.png", import.meta.url) });
console.log("screenshots saved to assets/");

const usage = await (await fetch("http://localhost:8788/usage")).json();
console.log("relay usage:", JSON.stringify(usage));
fs.writeFileSync(
  new URL("../assets/verify-result.json", import.meta.url),
  JSON.stringify({ stats, tiers: result.tiers, badges: result.badges, scores: result.scores, usage, pass, fail }, null, 1),
);

await browser.close();
console.log(`${pass} passed, ${fail} failed`);
if (fail) process.exit(1);

